Given an integer n, for every positive integer i <= n, the task is to print,"FizzBuzz" if i is divisible by 3 and 5, "Fizz" if i is divisible by 3,"Buzz" if i is divisible by 5"i" as a string, if none of the conditions are true.Examples:Input: n = 3Output: ["1", "2", "Fizz"]Input: n = 10Output: ["1", "2", "Fizz", "4", "Buzz", "Fizz", "7", "8", "Fizz", "Buzz"]Input: n = 20Output: ["1", "2", "Fizz", "4", "Buzz", "Fizz", "7", "8", "Fizz", "Buzz", "11", "Fizz", "13", "14", "FizzBuzz", "16", "17", "Fizz", "19", "Buzz"]Try It YourselfTable of Content[Naive Approach] By checking every integer individually[Better Approach] By String Concatenation[Expected Approach] Using Hash Map or Dictionary[Naive Approach] By checking every integer individuallyA very simple approach to solve this problem is that we can start checking each number from 1 to n to see if it's divisible by 3, 5, or both. Depending on the divisibility:If a number is divisible by both 3 and 5, append "FizzBuzz" into result.If it's only divisible by 3, append "Fizz" into result.If it's only divisible by 5, append "Buzz" into result.Otherwise, append the number itself into result.
            C++

    // C++ program for Fizz Buzz Problem 
// by checking every integer individually

#include <iostream>
#include <vector>
using namespace std;

vector<string> fizzBuzz(int n){
    vector<string> res;
    for (int i = 1; i <= n; ++i) {

        // Check if i is divisible by both 3 and 5
        if (i % 3 == 0 && i % 5 == 0) {

            // Add "FizzBuzz" to the result vector
            res.push_back("FizzBuzz");
        }

        // Check if i is divisible by 3
        else if (i % 3 == 0) {

            // Add "Fizz" to the result vector
            res.push_back("Fizz");
        }

        // Check if i is divisible by 5
        else if (i % 5 == 0) {

            // Add "Buzz" to the result vector
            res.push_back("Buzz");
        }
        else {

            // Add the current number as a string to the
            // result vector
            res.push_back(to_string(i));
        }
    }

    return res;
}

int main(){
    int n = 20;
    vector<string> res = fizzBuzz(n);
    for (const string& s : res) {
        cout << s << " ";
    }
    return 0;
}


